fix_code:
public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int a = sc.nextInt();
    int b = sc.nextInt();
    for(int i = 0; i < a; i++){
        int num = sc.nextInt();
        if(b == 1) {
            System.out.print(num + " ");
        } else if(num % b == 0){
            System.out.print(num / b + " ");
        }
    }
}

